import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Button, Spinner, Alert } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import { postsAPI, monumentsAPI } from '../../services/api';

const HomePage = () => {
  const [posts, setPosts] = useState([]);
  const [monuments, setMonuments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        const [postsResponse, monumentsResponse] = await Promise.all([
          postsAPI.getAll({ per_page: 3 }),
          monumentsAPI.getAll({ per_page: 8 })
        ]);

        setPosts(postsResponse.data.data);
        setMonuments(monumentsResponse.data.data);
      } catch (err) {
        setError('Failed to load content');
        console.error('Error fetching data:', err);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  if (loading) {
    return (
      <Container className="text-center py-5">
        <Spinner animation="border" role="status">
          <span className="visually-hidden">Loading...</span>
        </Spinner>
      </Container>
    );
  }

  if (error) {
    return (
      <Container className="py-5">
        <Alert variant="danger">{error}</Alert>
      </Container>
    );
  }

  // Group monuments by zone
  const monumentsByZone = monuments.reduce((acc, monument) => {
    if (!acc[monument.zone]) {
      acc[monument.zone] = [];
    }
    acc[monument.zone].push(monument);
    return acc;
  }, {});

  return (
    <div>
      {/* Hero Section */}
      <div className="bg-primary text-white py-5">
        <Container>
          <Row className="align-items-center">
            <Col lg={6}>
              <h1 className="display-4 fw-bold">Discover Historical Wonders</h1>
              <p className="lead">
                Explore the magnificent monuments and heritage sites that tell the story of our world's rich history.
              </p>
              <Button as={Link} to="/monuments" variant="light" size="lg">
                Explore Monuments
              </Button>
            </Col>
            <Col lg={6}>
              <div className="text-center">
                <i className="fas fa-landmark" style={{ fontSize: '8rem', opacity: 0.3 }}></i>
              </div>
            </Col>
          </Row>
        </Container>
      </div>

      {/* Stats Section */}
      <Container className="py-5">
        <Row className="text-center">
          <Col md={3}>
            <h3 className="text-primary">{monuments.length}</h3>
            <p>Total Monuments</p>
          </Col>
          <Col md={3}>
            <h3 className="text-primary">{posts.length}</h3>
            <p>Latest Posts</p>
          </Col>
          <Col md={3}>
            <h3 className="text-primary">4</h3>
            <p>Zones Covered</p>
          </Col>
          <Col md={3}>
            <h3 className="text-primary">∞</h3>
            <p>Stories to Tell</p>
          </Col>
        </Row>
      </Container>

      {/* Featured Posts */}
      <Container className="py-5">
        <Row>
          <Col>
            <h2 className="mb-4">Latest Posts</h2>
          </Col>
        </Row>
        <Row>
          {posts.map(post => (
            <Col md={4} key={post.id} className="mb-4">
              <Card className="h-100">
                {post.image && (
                  <Card.Img 
                    variant="top" 
                    src={`http://127.0.0.1:8000/storage/${post.image}`}
                    style={{ height: '200px', objectFit: 'cover' }}
                  />
                )}
                <Card.Body className="d-flex flex-column">
                  <Card.Title>{post.title}</Card.Title>
                  <Card.Text className="flex-grow-1">
                    {post.content.replace(/<[^>]*>/g, '').substring(0, 100)}...
                  </Card.Text>
                  <div className="mt-auto">
                    <small className="text-muted">
                      By {post.creator?.name} • {new Date(post.created_at).toLocaleDateString()}
                    </small>
                    <div className="mt-2">
                      <Button as={Link} to={`/posts/${post.id}`} variant="primary" size="sm">
                        Read More
                      </Button>
                    </div>
                  </div>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
        <Row>
          <Col className="text-center">
            <Button as={Link} to="/posts" variant="outline-primary">
              View All Posts
            </Button>
          </Col>
        </Row>
      </Container>

      {/* Featured Monuments by Zone */}
      <div className="bg-light py-5">
        <Container>
          <Row>
            <Col>
              <h2 className="mb-4">Monuments by Zone</h2>
            </Col>
          </Row>
          {Object.entries(monumentsByZone).map(([zone, zoneMonuments]) => (
            <div key={zone} className="mb-5">
              <h4 className="text-primary mb-3">{zone} Zone</h4>
              <Row>
                {zoneMonuments.slice(0, 2).map(monument => (
                  <Col md={6} key={monument.id} className="mb-3">
                    <Card>
                      {monument.image && (
                        <Card.Img 
                          variant="top" 
                          src={`http://127.0.0.1:8000/storage/${monument.image}`}
                          style={{ height: '200px', objectFit: 'cover' }}
                        />
                      )}
                      <Card.Body>
                        <Card.Title>{monument.title}</Card.Title>
                        <Card.Text>
                          {monument.description.substring(0, 100)}...
                        </Card.Text>
                        <Button as={Link} to={`/monuments/${monument.id}`} variant="primary" size="sm">
                          Learn More
                        </Button>
                      </Card.Body>
                    </Card>
                  </Col>
                ))}
              </Row>
            </div>
          ))}
          <Row>
            <Col className="text-center">
              <Button as={Link} to="/monuments" variant="outline-primary">
                View All Monuments
              </Button>
            </Col>
          </Row>
        </Container>
      </div>
    </div>
  );
};

export default HomePage;
